import React, { useState } from 'react'
import cn from 'classnames'
import { Flex } from '@Pimcore/components/flex/flex'
import { useTranslation } from 'react-i18next'
import { IconButton } from '@Pimcore/components/icon-button/icon-button'
import { Tooltip } from '@Pimcore/components/tooltip/tooltip'
import {
  LinkModal
} from '@Pimcore/modules/element/dynamic-types/definitions/objects/data-related/components/link/modal'
import _ from 'lodash'
import { useElementHelper } from '@Pimcore/modules/element/hooks/use-element-helper'
import {
  convertType
} from '@Pimcore/modules/element/dynamic-types/definitions/objects/data-related/components/link/utils/link-value-converter'
import { useStyles } from './link.styles'
import { LinkPreview } from './components/link-preview/link-preview'

export interface LinkValue {
  text: string
  linktype: 'direct' | 'internal'
  direct?: string | null
  internal?: number | null
  internalType?: string | null
  fullPath?: string
  target: string | null
  parameters: string
  anchor: string
  title: string
  accesskey: string
  rel: string
  tabindex: string
  class: string

}

export interface LinkProps {
  disabled?: boolean
  inherited?: boolean
  value?: LinkValue | null
  onChange?: (value?: LinkValue | null) => void
  allowedTypes: string[]
  allowedTargets: string[]
  disabledFields: string[]
  className?: string
}

export const Link = (props: LinkProps): React.JSX.Element => {
  const [isModalVisible, setIsModalVisible] = useState(false)

  console.log('----->>>>>> Link props: ', props)

  const { t } = useTranslation()
  const { styles } = useStyles()
  const { openElement } = useElementHelper()

  const value = props.value ?? null

  const handleChange = (value: LinkValue | null): void => {
    props.onChange?.(value)
  }

  const showModal = (): void => {
    setIsModalVisible(true)
  }

  const hideModal = (): void => {
    setIsModalVisible(false)
  }

  const openLink = (): void => {
    if (value === null) {
      return
    }
    if (value.linktype === 'direct' && value.direct !== null && !_.isEmpty(value.direct)) {
      window.open(value.direct, '_blank')
    }

    const internalType = convertType(value.internalType ?? null)
    const internal = value.internal ?? null

    if (value.linktype === 'internal' && internalType !== null && internal !== null) {
      openElement({
        type: internalType,
        id: internal
      }).catch((error) => {
        console.error('Error while opening element:', error)
      })
    }
  }

  return (
    <Flex
      align="center"
      className={ cn(styles.link, props.className) }
      gap="extra-small"
    >
      <LinkPreview
        className="studio-inherited-overlay"
        inherited={ props.inherited }
        value={ value }
      />

      <Tooltip
        key="open"
        title={ t('open') }
      >
        <IconButton
          disabled={ value === null || _.isEmpty(value.fullPath) }
          icon={ { value: 'open-folder' } }
          onClick={ openLink }
          type="default"
        />
      </Tooltip>

      { props.disabled !== true
        ? (
          <Tooltip
            key="edit"
            title={ t('edit') }
          >
            <IconButton
              icon={ { value: 'edit' } }
              onClick={ showModal }
              type="default"
            />
          </Tooltip>
          )
        : (
          <Tooltip
            key="details"
            title={ t('details') }
          >
            <IconButton
              icon={ { value: 'info-circle' } }
              onClick={ showModal }
              type="default"
            />
          </Tooltip>
          ) }

      <LinkModal
        allowedTargets={ props.allowedTargets }
        allowedTypes={ props.allowedTypes }
        disabled={ props.disabled }
        disabledFields={ props.disabledFields }
        onClose={ hideModal }
        onSave={ handleChange }
        open={ isModalVisible }
        value={ value }
      />

    </Flex>
  )
}
